import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterAll, describe, expect, test } from 'vitest';
import { openDays } from '../src/lib/cart';
import { STATIC_MENU } from '../src/lib/menu';

// docs/domain.md, "The seed": 24 items in 5 categories, 48 variants. The storefront's static menu
// is the seed's, regenerated by scripts/menu.mjs; CI's `verify` job compares the committed file.

const script = fileURLToPath(new URL('../scripts/menu.mjs', import.meta.url));
const committed = fileURLToPath(new URL('../src/data/menu.json', import.meta.url));

const hasCargo = spawnSync('cargo', ['--version']).status === 0;
if (!hasCargo) {
  console.warn('menu.test.ts: cargo is not installed, so the regeneration check is skipped.');
}

const temp = mkdtempSync(join(tmpdir(), 'bakery-menu-'));
afterAll(() => rmSync(temp, { recursive: true, force: true }));

describe('src/data/menu.json', () => {
  test.skipIf(!hasCargo)(
    'matches a fresh run of the seed, byte for byte',
    () => {
      const out = join(temp, 'menu.json');
      const run = spawnSync('node', [script, out], { encoding: 'utf8' });
      expect(run.status, run.stderr).toBe(0);
      expect(
        readFileSync(committed, 'utf8'),
        'menu.json is stale: run `node apps/web/scripts/menu.mjs`',
      ).toBe(readFileSync(out, 'utf8'));
    },
    600_000,
  );

  test('holds the seed menu: 5 categories, 24 items, 48 variants', () => {
    expect(STATIC_MENU.categories.map((c) => c.slug)).toEqual([
      'breads',
      'pastries',
      'cakes',
      'savory',
      'drinks',
    ]);
    const items = STATIC_MENU.categories.flatMap((c) => c.items);
    expect(items).toHaveLength(24);
    expect(items.flatMap((i) => i.variants)).toHaveLength(48);
  });

  test('every price is a positive integer count of cents', () => {
    for (const category of STATIC_MENU.categories) {
      for (const item of category.items) {
        for (const v of item.variants) {
          expect(Number.isInteger(v.price_cents) && v.price_cents > 0, v.slug).toBe(true);
          expect(v.slug.startsWith(`${item.slug}/`)).toBe(true);
        }
      }
    }
  });

  test('cakes need 48 hours but a slice, drinks need none and are pickup only', () => {
    const cakes = STATIC_MENU.categories.find((c) => c.slug === 'cakes')!;
    const leads = cakes.items.flatMap((i) => i.variants.map((v) => [v.label, v.lead_minutes]));
    expect(leads.filter(([label]) => label !== 'Slice').every(([, m]) => m === 2880)).toBe(true);
    const drinks = STATIC_MENU.categories.find((c) => c.slug === 'drinks')!;
    expect(drinks.items.every((i) => i.pickup_only)).toBe(true);
    expect(drinks.items.flatMap((i) => i.variants).every((v) => v.lead_minutes === 0)).toBe(true);
  });

  test('the bakery is closed on Mondays: no item is baked then', () => {
    expect(openDays(STATIC_MENU).has('mon')).toBe(false);
    expect([...openDays(STATIC_MENU)].sort()).toEqual(['fri', 'sat', 'sun', 'thu', 'tue', 'wed']);
  });
});
